// CONFIDENCE: MEDIUM - iteration and self/local-peer inversion read in full. Original 0x1423af010.
bool bResult = false;
const bool bThisIsLocal = IsLocalController();
UWorld* World = GetWorld();
if (World)
{
    for (int32 Index = 0; Index < World->PlayerControllerList.Num(); ++Index)
    {
        APlayerController* Other = World->PlayerControllerList[Index].Get();
        if (!Other || !Other->IsA(AFortPlayerController::StaticClass()))
        {
            continue;
        }
        if (Other == this || (bThisIsLocal && Other->IsLocalController()))
        {
            // Self and local peers get the inverted flag.
            bResult |= Other->NativeSetComponentHiddenForController(SceneComp, !bNewHidden, bPropagateToChildren);
        }
        else
        {
            bResult |= Other->NativeSetComponentHiddenForController(SceneComp, bNewHidden, bPropagateToChildren);
        }
    }
}
return bResult;
